def generate_keys():
    private_key = (
        subprocess.check_output("wg genkey", shell=True).strip().decode("utf-8")
    )
    public_key = (
        subprocess.check_output(f"echo {private_key} | wg pubkey", shell=True)
        .strip()
        .decode("utf-8")
    )
    return private_key, public_key


