    while True:
        server_type = input("\033[38;5;205mEnter your choice Please: \033[0m")
        if server_type == "1":
            wireguard_noconjuction_kharej1_5iran()
            break
        elif server_type == "2":
            wireguard_noconjuction_1iran_5kharej()
            break
