        if choice == "2":
            new_ip = input(
                "\033[93mEnter new Private IPV4 address \033[96m[VXLAN]\033[93m :\033[0m "
            )
            if new_ip:
                vxlan_ip_vxlan = new_ip
            else:
                print("\033[91mWrong IP address\033[0m")
        elif choice == "1":
            new_ip = input("\033[93mEnter \033[92mKharej\033[93m Public IP :\033[0m ")
