def update_ipsec_ip_multi2(new_vxlan_ip):
    def opposite_ip(ip):
        if ":" in ip:
            parts = ip.split(":")
            if parts[-1].endswith("1"):
                parts[-1] = parts[-1][:-1] + "2"
            else:
                parts[-1] = parts[-1][:-1] + "1"
            return ":".join(parts)
        else:
            octets = ip.split(".")
            if octets[-1] == "1":
                octets[-1] = "2"
            else:
                octets[-1] = "1"
            return ".".join(octets)

    secrets_file = "/etc/ipsec.secrets"
    opposite_ip_addr = opposite_ip(new_vxlan_ip)

    with open(secrets_file, "r") as file:
        lines = file.readlines()

    if len(lines) < 2:
        raise ValueError("The secrets file doesn't have at least 2 lines")

    new_lines = []
    for index, line in enumerate(lines):
        if index == 1 and ": PSK" in line:
            parts = line.split()
            if len(parts) > 2:
                new_line = (
                    f'{opposite_ip_addr} {new_vxlan_ip} : PSK "{parts[-1][1:-1]}"'
                )
                new_lines.append(new_line + "\n")
            else:
                new_lines.append(line)
        else:
            new_lines.append(line)

    with open(secrets_file, "w") as file:
        file.writelines(new_lines)


