def enable_ipv45forward():
    print("\033[93m────────────────────────────────────────\033[0m")
    ip4_enable = input(
        "\033[93mDo you want \033[92mIPV4/6 \033[93mto be checked & enabled every minute? (\033[92myes\033[93m/\033[91mno\033[93m):\033[0m "
    ).lower()
    if ip4_enable in ["yes", "y"]:
        ipv4forwardipv6()
        ipv4_service()


def ipv4forwardipv6():
    script_content = """#!/bin/bash

set_sysctl_value() {
    local key="$1"
    local value="$2"

    sysctl -w $key=$value
    
    if grep -q "^$key" /etc/sysctl.conf; then
        sed -i "s/^$key.*/$key = $value/" /etc/sysctl.conf
    else
        echo "$key = $value" >> /etc/sysctl.conf
    fi
}

while true; do
    set_sysctl_value net.ipv4.ip_forward 1
    set_sysctl_value net.ipv6.conf.all.disable_ipv6 0
    set_sysctl_value net.ipv6.conf.default.disable_ipv6 0
    set_sysctl_value net.ipv6.conf.all.forwarding 1
    
    sleep 60
done
"""
    script_path = "/etc/ipv4.sh"
    with open(script_path, "w") as f:
        f.write(script_content)

    os.chmod(script_path, 0o755)


def ipv4_service():
    service_content = """[Unit]
Description=Azumi local Service reset
After=network.target

[Service]
Type=simple
Restart=always    
LimitNOFILE=1048576
ExecStart=/etc/ipv4.sh

[Install]
WantedBy=multi-user.target
"""
    with open("/etc/systemd/system/ipv4.service", "w") as f:
        f.write(service_content)
    subprocess.run(["systemctl", "daemon-reload"])
    subprocess.run(["systemctl", "enable", "ipv4"])
    subprocess.run(["systemctl", "restart", "ipv4"])


