    if choice in ["y", "yes"]:
        subprocess.run(
            [
                "bash",
                "-c",
                "python3 <(curl -Ls https://raw.githubusercontent.com/kalilovers/6TO4-all/main/oep.py --ipv4)",
            ]
        )
    elif choice in ["n", "no"]:
        pass
    else:
        print("\033[91mWrong choice! Plz try again..\033[0m")

