def kharej_vxlan_v4p2p():
    print("\033[92m ^ ^\033[0m")
    print("\033[92m(\033[91mO,O\033[92m)\033[0m")
    print("\033[92m(   ) \033[93mConfiguring Vxlan P2P \033[92mKharej\033[0m")
    print('\033[92m "-"\033[93m═══════════════════════════════════\033[0m')
    display_notification(
        "\033[93mAdding Vxlan IP addresses for Kharej server...\033[0m"
    )

    if os.path.isfile("/usr/local/bin/bridge.sh"):
        os.remove("/usr/local/bin/bridge.sh")

    print("\033[93m╭─────────────────────────────────────────────────────────╮\033[0m")
    local_ip = input("\033[93mEnter \033[92mKharej \033[93mIPV4 address: \033[0m")
    remote_ip = input("\033[93mEnter \033[92mIRAN\033[93m IPV4 address: \033[0m")
    dst_port = input("\033[93mEnter \033[92mdestination port\033[93m: \033[0m")
    print("\033[93m╰─────────────────────────────────────────────────────────╯\033[0m")
    ufwport(dst_port)
    ufw(remote_ip)
    ufw("30.0.0.1")
    ufw("30.0.0.2")
    find_interface = input(
        "\033[93mDo you want meh to find the \033[92mmain interface\033[96m automatically\033[93m? (\033[92myes\033[93m/\033[91mno\033[93m): \033[0m"
    )
    if find_interface.lower() == "yes" or find_interface.lower() == "y":
        interface = main_interface()
        if interface is None:
            print("\033[91merror: Couldn't find your network interface.\033[0m")
            return
    else:
        interface = input(
            "\033[93mWhat is your \033[92mmain interface\033[93m? \033[0m"
        )

    subprocess.run(
        [
            "sudo",
            "ip",
            "link",
            "add",
            "vxlan",
            "type",
            "vxlan",
            "id",
            "88",
            "local",
            local_ip,
            "remote",
            remote_ip,
            "dev",
            interface,
            "dstport",
            dst_port,
        ],
        stdout=subprocess.DEVNULL,
    )
    subprocess.run(
        ["sudo", "ip", "addr", "add", "30.0.0.1/24", "dev", "vxlan"],
        stdout=subprocess.DEVNULL,
    )
    subprocess.run(
        ["sudo", "ip", "link", "set", "vxlan", "up"], stdout=subprocess.DEVNULL
    )

    with open("/usr/local/bin/bridge.sh", "w") as f:
        f.write(
            f"sudo ip link add vxlan type vxlan id 88 local {local_ip} remote {remote_ip} dev {interface} dstport {dst_port}\n"
        )
        f.write("sudo ip addr add 30.0.0.1/24 dev vxlan\n")
        f.write("sudo ip link set vxlan up\n")

    set_mtu = input(
        "\033[93mDo you want to set the \033[92mMTU\033[96m [Vxlan]\033[93m? (\033[92myes\033[93m/\033[91mno\033[93m): \033[0m"
    )
    if set_mtu.lower() == "yes" or set_mtu.lower() == "y":
        mtu_value = input(
            "\033[93mEnter the desired\033[92m MTU value\033[93m: \033[0m"
        )
        mtu_command = f"ip link set dev vxlan mtu {mtu_value}\n"
        with open("/usr/local/bin/bridge.sh", "a") as f:
            f.write(mtu_command)
        subprocess.run(mtu_command, shell=True, check=True)

    display_checkmark("\033[92mVxlan ip added successfully!\033[0m")
    file_path = "/usr/local/bin/bridge.sh"
    command = f"chmod +x {file_path}"
    subprocess.run(command, shell=True, check=True)

    vxlan_cron_job()

    display_checkmark("\033[92mkeepalive service Configured!\033[0m")
    vxlan_ping1()
    sleep(1)

