def remote_ip_vx2():
    gen_path = "/usr/local/bin/bridge.sh"

    if not os.path.isfile(gen_path):
        return None

    with open(gen_path, "r") as gen_sh:
        for line in gen_sh:
            if "sudo bridge fdb append" in line:
                parts = line.split()
                remote_ip = parts[-3]
                return remote_ip

    return None


def remote_ip_vx():
    gen_path = "/usr/local/bin/bridge.sh"

    if not os.path.isfile(gen_path):
        return None

    with open(gen_path, "r") as gen_sh:
        for line in gen_sh:
            if "remote" in line:
                parts = line.split()
                remote_index = parts.index("remote")
                remote_ip = parts[remote_index + 1]
                remote_ip = remote_ip.strip('"')

                return remote_ip

    return None


def remove_vxlansec():
    os.system("clear")
    delete_cron1()
    delete_cron2()
    remote_ip = remote_ip_vx()

    if remote_ip is None:
        print("Unable to retrieve remote IP")
    else:
        delufw(remote_ip)
    remote_ip2 = remote_ip_vx2()

    if remote_ip2 is None:
        print("Unable to retrieve FDB remote IP")
    else:
        delufw(remote_ip2)
    delufw("30.0.0.1")
    delufw("30.0.0.2")
    delufw("2001:db8:0:1::2")
    delufw("2001:db8:0:1::1")
    print("\033[93m───────────────────────────────────────\033[0m")
    display_notification(
        "\033[93mRemoving \033[92mVxlan + IPsec\033[93m Tunnel...\033[0m"
    )
    print("\033[93m───────────────────────────────────────\033[0m")

    try:
        if (
            subprocess.call(
                "test -f /usr/local/bin/bridge.sh > /dev/null 2>&1", shell=True
            )
            == 0
        ):
            subprocess.run("rm /usr/local/bin/bridge.sh > /dev/null 2>&1", shell=True)

        display_notification("\033[93mRemoving cronjob...\033[0m")
        subprocess.run(
            'crontab -l | grep -v "@reboot /bin/bash /usr/local/bin/bridge.sh" | crontab -',
            shell=True,
        )
        subprocess.run("sudo rm /etc/ipsec1.conf > /dev/null 2>&1", shell=True)
        subprocess.run("sudo rm /etc/ipsec.secrets > /dev/null 2>&1", shell=True)
        subprocess.run("systemctl stop strong-azumi1 > /dev/null 2>&1", shell=True)
        subprocess.run("systemctl disable strong-azumi1 > /dev/null 2>&1", shell=True)
        subprocess.run(
            "rm /etc/systemd/system/strong-azumi1.service > /dev/null 2>&1", shell=True
        )

        subprocess.run("sudo rm /etc/ping_vxlan.sh", shell=True)

        subprocess.run(
            "systemctl disable ping_vxlan_service > /dev/null 2>&1", shell=True
        )
        subprocess.run("systemctl stop ping_vxlan_service > /dev/null 2>&1", shell=True)
        subprocess.run(
            "rm /etc/systemd/system/ping_vxlan_service.service > /dev/null 2>&1",
            shell=True,
        )
        time.sleep(1)
        subprocess.run("systemctl daemon-reload", shell=True)

        subprocess.run("ip link set dev vxlan down > /dev/null", shell=True)
        subprocess.run("ip link delete vxlan > /dev/null", shell=True)
        subprocess.run("ip link delete azumibr > /dev/null", shell=True)
        sleep(1)
        subprocess.run("apt purge strongswan -y > /dev/null", shell=True)
        subprocess.run("systemctl stop strongswan > /dev/null 2>&1", shell=True)
        subprocess.run("systemctl disable strongswan > /dev/null 2>&1", shell=True)
        subprocess.run("systemctl stop strongswan-starter > /dev/null 2>&1", shell=True)
        subprocess.run(
            "systemctl disable strongswan-starter > /dev/null 2>&1", shell=True
        )
        print("Progress: ", end="")

        frames = ["⠋", "⠙", "⠹", "⠸", "⠼", "⠴", "⠦", "⠧", "⠇", "⠏"]
        delay = 0.1
        duration = 1
        end_time = time.time() + duration

        while time.time() < end_time:
            for frame in frames:
                print("\r[%s] Loading...  " % frame, end="")
                time.sleep(delay)
                print("\r[%s]             " % frame, end="")
                time.sleep(delay)

        display_checkmark("\033[92mUninstall completed!\033[0m")
    except subprocess.CalledProcessError as e:
        print("Error:", e.output.decode().strip())


