def remote_ip_gen4():
    gen_path = "/etc/sys4.sh"

    if not os.path.isfile(gen_path):
        return None

    with open(gen_path, "r") as gen_sh:
        for line in gen_sh:
            if "remote" in line:
                remote_ip = line.split()[-1].strip('"')
                return remote_ip

    return None


