    display_notification(
        "\033[93mAdding private IP addresses for Iran server...\033[0m"
    )

    if os.path.isfile("/etc/private1.sh"):
        os.remove("/etc/private1.sh")

    print("\033[93m╭─────────────────────────────────────────────────────────╮\033[0m")
