def iran_ping3():
    try:
        subprocess.run(
            ["ping", "-c", "2", "2002:821b::1"], check=True, stdout=subprocess.DEVNULL
        )
    except subprocess.CalledProcessError as e:
        print(Fore.LIGHTRED_EX + "Pinging failed:", e, Style.RESET_ALL)


