    initial_ip = "2002:841b::2/64"
    subprocess.run(
        ["ip", "addr", "add", initial_ip, "dev", "azumi2"], stdout=subprocess.DEVNULL
    )

    subprocess.run(
        ["ip", "-6", "route", "add", "2002:841b::1/64", "dev", "azumi2"],
        stdout=subprocess.DEVNULL,
    )

    display_notification("\033[93mAdding commands...\033[0m")
