def kharej1server_mtuisa_mnu():
    print("\033[93m───────────────────────────────────────\033[0m")
    display_notification("\033[93m              Server \033[0m")
    print("\033[93m───────────────────────────────────────\033[0m")
    mtu_value = input(
        "\033[93mEnter the \033[92mMTU value \033[93m[ \033[96mISATAP\033[93m]:\033[0m "
    )
    mtu_command = f"ip link set dev azumiserver mtu {mtu_value}\n"

    if os.path.exists("/usr/local/bin/isatap.sh"):
        with open("/usr/local/bin/isatap.sh", "r") as file:
            sh_contents = file.readlines()

        if any("link set dev azumiserver mtu" in line for line in sh_contents):
            sh_contents = [
                line
                for line in sh_contents
                if "link set dev azumiserver mtu" not in line
            ]

            with open("/usr/local/bin/isatap.sh", "w") as file:
                file.writelines(sh_contents)

        with open("/usr/local/bin/isatap.sh", "a") as file:
            file.write(mtu_command)

        print("\033[92mMTU command edited successfully\033[0m")
        subprocess.run(mtu_command, shell=True)
    else:
        print("\033[91mCommand file doesn't exist\033[0m")


