def reset_local(interval):
    service_name = "isatapreset.service"

    daemon_script_content = f"""#!/bin/bash
INTERVAL={interval}

while true; do
    /bin/bash /etc/reset_isatap.sh
    sleep $INTERVAL
done
"""

    with open("/usr/local/bin/isatap_daemon.sh", "w") as daemon_script_file:
        daemon_script_file.write(daemon_script_content)

    subprocess.run(["chmod", "+x", "/usr/local/bin/isatap_daemon.sh"])

    service_content = f"""[Unit]
Description=Custom IPSEC Daemon

[Service]
ExecStart=/usr/local/bin/isatap_daemon.sh
Restart=always

[Install]
WantedBy=multi-user.target
"""

    with open(f"/etc/systemd/system/{service_name}", "w") as service_file:
        service_file.write(service_content)

    ipsec_reset_script_content = """#!/bin/bash
ip link delete azumiserver
/bin/bash /usr/local/bin/isatap.sh
sudo systemctl restart strong-azumi1
"""

    with open("/etc/reset_isatap.sh", "w") as script_file:
        script_file.write(ipsec_reset_script_content)

    subprocess.run(["chmod", "+x", "/etc/reset_isatap.sh"])
    subprocess.run(["systemctl", "daemon-reload"])
    subprocess.run(["systemctl", "enable", "--now", service_name])
    subprocess.run(["systemctl", "restart", service_name])


