    load_balance(server_ipv6, kharej_servers_data)
    print("\033[93m────────────────────────────────────────\033[0m")
    ipsec_enable = input(
        "\033[93mDo you want \033[92mIPSEC Encryption \033[93mto be enabled ? (\033[92myes\033[93m/\033[91mno\033[93m):\033[0m "
    ).lower()
    if ipsec_enable in ["yes", "y"]:
        psk = input("\033[93mEnter \033[92mIPSEC \033[93mSecret Key :\033[0m ")
        config_server(psk, server_ipv6, kharej_servers_data)
        print("\033[93m────────────────────────────────────────\033[0m")
        enable_reset_ipsec()
        print("\033[93m────────────────────────────────────────\033[0m")
    for index, (client_ipv6, _) in enumerate(kharej_servers_data, start=1):
        ping_keepalive(client_ipv6, index)
        isa_service(index)
    print("\033[93m────────────────────────────────────────\033[0m")
    enable_reset = input(
        "\033[93mDo you want to enable \033[96mISATAP \033[92mreset time\033[93m? (\033[92myes\033[93m/\033[91mno\033[93m): \033[0m"
    ).lower()
    if enable_reset in ["yes", "y"]:
        print("\033[93m╭───────────────────────────────────────╮\033[0m")
        print("1. \033[92mHour\033[0m")
        print("2. \033[93mMinute\033[0m")
        print("\033[93m╰───────────────────────────────────────╯\033[0m")

        time_unit_choice = input("\033[93mEnter your choice :\033[0m ").strip()
        if time_unit_choice == "1":
            time_unit = "hour"
        elif time_unit_choice == "2":
            time_unit = "minute"
        else:
            print("\033[91mWrong choice\033[0m")
            return

        time_value = input(
            "\033[93mEnter the \033[92mdesired input\033[93m:\033[0m "
        ).strip()
        interval_seconds = (
            int(time_value) * 3600 if time_unit == "hour" else int(time_value) * 60
        )
        reset_local(interval_seconds)
        reset_ping_isatapclient(client_ipv6_list)
        resetping_service_isatap()
        print("\033[93m────────────────────────────────────────\033[0m")

    animate("\033[92mIRAN Server Configuration is completed!\033[0m")


