def prefix(ipv4):
    octets = ipv4.split(".")
    hex_parts = [format(int(octet), "02x") for octet in octets]
    return f"2001:db8::5efe:{hex_parts[0]}{hex_parts[1]}:{hex_parts[2]}{hex_parts[3]}"


