def ipsecs_uninstall():
    delete_cron1()
    delete_cron2()
    remove_private()
    remove_gre621()
    print("\033[93m───────────────────────────────────────\033[0m")
    display_notification(
        "\033[93mRemoving Erspan + \033[92mIpsec \033[93m+ Tunnels\033[0m"
    )
    print("\033[93m───────────────────────────────────────\033[0m")

    try:
        if subprocess.call("test -f /etc/spn.sh", shell=True) == 0:
            subprocess.run("rm /etc/spn.sh", shell=True)

        display_notification("\033[93mRemoving cronjob...\033[0m")
        subprocess.run(
            'crontab -l | grep -v "@reboot /bin/bash /etc/spn.sh" | crontab -',
            shell=True,
        )
        devnull = open(os.devnull, "w")
        subprocess.run(
            "sudo rm /etc/ipsec.conf", shell=True, stdout=devnull, stderr=devnull
        )
        subprocess.run(
            "sudo rm /etc/ipsec.secrets", shell=True, stdout=devnull, stderr=devnull
        )
        subprocess.run(
            "systemctl disable strongswan-starter > /dev/null 2>&1", shell=True
        )
        subprocess.run("systemctl stop strongswan-starter > /dev/null 2>&1", shell=True)
        subprocess.run("systemctl disable strongswan > /dev/null 2>&1", shell=True)
        subprocess.run("systemctl stop strongswan > /dev/null 2>&1", shell=True)

        subprocess.run("apt purge strongswan -y", shell=True)
        subprocess.run(
            "systemctl disable ping_espan.service > /dev/null 2>&1", shell=True
        )
        subprocess.run("systemctl stop ping_espan.service > /dev/null 2>&1", shell=True)
        subprocess.run(
            "rm /etc/systemd/system/ping_espan.service > /dev/null 2>&1", shell=True
        )

        subprocess.run("systemctl daemon-reload", shell=True)

        subprocess.run("sudo ip link delete azumiespn > /dev/null", shell=True)
        devnull.close()
        print("Progress: ", end="")

        frames = ["⠋", "⠙", "⠹", "⠸", "⠼", "⠴", "⠦", "⠧", "⠇", "⠏"]
        delay = 0.1
        duration = 1
        end_time = time.time() + duration

        while time.time() < end_time:
            for frame in frames:
                print("\r[%s] Loading...  " % frame, end="")
                time.sleep(delay)
                print("\r[%s]             " % frame, end="")
                time.sleep(delay)

        display_checkmark("\033[92mUninstall completed!\033[0m")
    except subprocess.CalledProcessError as e:
        print("Error:", e.output.decode().strip())
    except Exception as e:
        print("Error:", str(e))


