    with open("/etc/sys.sh", "w") as f:
        f.write(
            f"sudo ip link add name azumigen type geneve id 1000 remote 2002:831a::2\n"
        )
        f.write("sudo ip link set azumigen up\n")
        f.write("sudo ip addr add 66.200.1.1/32 dev azumigen\n")
        f.write("sudo ip route add 66.200.2.1/32 dev azumigen\n")

