def check_gre6():
    with open("/etc/gre6.sh", "r") as file:
        lines = file.readlines()
        for line in lines:
            if "azumig6" in line and "ip6gretap" in line:
                return "gre6tap"
            elif "azumig6" in line and "ip6gre" in line:
                return "gre6"
    return "unknown"


